import React from 'react';
import './footer.css';

function Footer() {
  return (
    <footer className="bb-footer">
      <div className="container bb-footer__inner">
        <div className="bb-footer__left">
          <div className="bb-footer__brand">
            <span className="bb-footer__dot" aria-hidden="true" />
            <span className="bb-footer__text">Fashion Boutique</span>
          </div>
          <div className="bb-footer__copy">
            © {new Date().getFullYear()} • Đồ án thực hành phân tầng ASP.NET Core Web API + React
          </div>
        </div>

        <div className="bb-footer__right">
          <a className="bb-footer__link" href="#" onClick={(e) => e.preventDefault()}>
            <i className="fa-regular fa-circle-question" /> Hỗ trợ
          </a>
          <a
            className="bb-footer__link"
            href="#"
            onClick={(e) => {
              e.preventDefault();
              window.scrollTo({ top: 0, behavior: 'smooth' });
            }}
          >
            <i className="fa-solid fa-arrow-up" /> Lên đầu
          </a>
        </div>
      </div>
    </footer>
  );
}

export default Footer;
